CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS public.owner_vault (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), owner_name TEXT NOT NULL DEFAULT 'Shaik Mujahid', primary_business_email TEXT NOT NULL DEFAULT 'info@ccmotocrafts.in', telemetry_gmail TEXT NOT NULL DEFAULT 'aisupport.on@gmail.com', backup_personal_gmail TEXT, pin_hash TEXT NOT NULL, otp_code_hash TEXT, otp_expires_at TIMESTAMPTZ, updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS public.staff_access (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), full_name TEXT NOT NULL, role TEXT NOT NULL CHECK (role IN ('partner_2w', 'partner_4w', 'service_manager', 'marketing_manager', 'advisor')), email TEXT NOT NULL UNIQUE, phone TEXT NOT NULL UNIQUE, passcode_hash TEXT NOT NULL, device_id TEXT, is_active BOOLEAN NOT NULL DEFAULT TRUE, can_bill BOOLEAN NOT NULL DEFAULT TRUE, can_use_ai BOOLEAN NOT NULL DEFAULT TRUE, is_profile_locked BOOLEAN NOT NULL DEFAULT FALSE, workshop_name TEXT, workshop_address TEXT, gps_coords TEXT, id_proof_url TEXT, gst_number TEXT, trade_license TEXT, last_seen TIMESTAMPTZ DEFAULT NOW(), created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS public.system_settings (id INT PRIMARY KEY DEFAULT 1, hotline_display TEXT NOT NULL DEFAULT '+91 8333084261', whatsapp_digits TEXT NOT NULL DEFAULT '918333084261', primary_email TEXT NOT NULL DEFAULT 'info@ccmotocrafts.in', telemetry_gmail TEXT NOT NULL DEFAULT 'aisupport.on@gmail.com', backup_gmail TEXT DEFAULT '', brand_2w_name TEXT NOT NULL DEFAULT 'CC Motocrafts AI Engine Labs Service', brand_4w_name TEXT NOT NULL DEFAULT 'CarS CareS Motocrafts Ai Engine Labs Service', active_languages JSONB DEFAULT '["EN","HI","TE","UR","AR"]'::jsonb, regions JSONB DEFAULT '[{"city":"Hyderabad","currency":"₹","phone":"+91 8333084261"}]'::jsonb, active_ai_provider TEXT NOT NULL DEFAULT 'gemini', gemini_api_key TEXT DEFAULT '', openai_api_key TEXT DEFAULT '', claude_api_key TEXT DEFAULT '', updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS public.services_catalog (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), division TEXT NOT NULL, cc_tier TEXT NOT NULL, title TEXT NOT NULL, description TEXT NOT NULL, price_inr NUMERIC(10,2) NOT NULL, warranty_term TEXT NOT NULL DEFAULT '30-Day Workmanship Guarantee', is_live BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS public.bookings (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), booking_code TEXT NOT NULL UNIQUE, customer_name TEXT NOT NULL, customer_phone TEXT NOT NULL, division TEXT NOT NULL CHECK (division IN ('2w', '4w')), brand TEXT NOT NULL, fuel_type TEXT NOT NULL CHECK (fuel_type IN ('Petrol', 'Diesel', 'CNG-LPG Gas')), cc_tier TEXT NOT NULL, vehicle_model TEXT NOT NULL, warranty_term TEXT NOT NULL DEFAULT '30-Day Workmanship Guarantee', gps_coords TEXT, utm_source TEXT DEFAULT 'direct', status TEXT NOT NULL DEFAULT 'BOOKED', quotation_approved BOOLEAN NOT NULL DEFAULT FALSE, media_proof_uploaded BOOLEAN NOT NULL DEFAULT FALSE, assigned_partner_id UUID REFERENCES public.staff_access(id), created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS public.job_tracking (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), booking_id UUID NOT NULL REFERENCES public.bookings(id) ON DELETE CASCADE, live_video_enabled BOOLEAN NOT NULL DEFAULT TRUE, gps_tracking_enabled BOOLEAN NOT NULL DEFAULT TRUE, call_timestamp TIMESTAMPTZ, call_duration_sec INTEGER DEFAULT 0, call_recording_url TEXT, updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE OR REPLACE FUNCTION public.verify_owner_pin(input_pin TEXT) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER AS $$ DECLARE v_row public.owner_vault%ROWTYPE; BEGIN SELECT * INTO v_row FROM public.owner_vault LIMIT 1; IF NOT FOUND THEN RETURN jsonb_build_object('ok', false, 'error', 'Owner vault not initialized'); END IF; IF v_row.pin_hash = crypt(input_pin, v_row.pin_hash) THEN RETURN jsonb_build_object('ok', true, 'owner_name', v_row.owner_name, 'primary_email', v_row.primary_business_email, 'telemetry_gmail', v_row.telemetry_gmail, 'backup_gmail', v_row.backup_personal_gmail); END IF; RETURN jsonb_build_object('ok', false, 'error', 'Invalid Master PIN'); END; $$;
CREATE OR REPLACE FUNCTION public.update_owner_pin(current_pin TEXT, new_pin TEXT) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER AS $$ DECLARE v_row public.owner_vault%ROWTYPE; BEGIN SELECT * INTO v_row FROM public.owner_vault LIMIT 1; IF NOT FOUND OR v_row.pin_hash <> crypt(current_pin, v_row.pin_hash) THEN RETURN jsonb_build_object('ok', false, 'error', 'Current PIN verification failed'); END IF; UPDATE public.owner_vault SET pin_hash = crypt(new_pin, gen_salt('bf', 10)), updated_at = NOW() WHERE id = v_row.id; RETURN jsonb_build_object('ok', true, 'message', 'Master Owner PIN updated securely'); END; $$;
ALTER TABLE public.owner_vault ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.staff_access ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.system_settings ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.services_catalog ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.bookings ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.job_tracking ENABLE ROW LEVEL SECURITY;
ALTER PUBLICATION supabase_realtime ADD TABLE public.staff_access;
ALTER PUBLICATION supabase_realtime ADD TABLE public.job_tracking;
ALTER PUBLICATION supabase_realtime ADD TABLE public.bookings;
